CAT = "cacesChargement"; SEG = "CHA"
# Exploitation : chargement et déchargement des véhicules (protocole de sécurité, calage,
# immobilisation), gerbage, stockage en palettier, palettes et charges particulières.
# Sources : R489 annexe 2 (G et savoir-faire B) et annexe 3/1 ; INRS ED 766, § 2.5, 3.3, 3.6.
Q = [
("Quel document fixe les règles d'une opération de chargement entre un transporteur et le site d'accueil ?",
 "Le protocole de sécurité", ["Le carnet d'entretien", "La notice du chariot", "La lettre de voiture du transport"],
 "R489, annexe 2 (G) et 3.4.1 : le protocole de sécurité décrit les consignes de chargement et de déchargement et les mesures de prévention ; le cariste doit le connaître."),
("Avant d'entrer dans un camion à quai, que doit-on garantir pour le camion ?",
 "Qu'il est immobilisé", ["Qu'il a le moteur allumé", "Qu'il a son réservoir plein", "Qu'il a ses portes fermées"],
 "INRS ED 766, § 3.3 : on ne s'engage jamais sur un pont de liaison sans être certain que le moyen de transport (wagon, camion) ne peut pas se déplacer."),
("Avant d'entrer avec le chariot dans la remorque, que vérifiez-vous sur le plancher ?",
 "Sa résistance", ["Son essence de bois", "Sa largeur seule", "Sa date de fabrication"],
 "R489, annexe 2, savoir-faire : on vérifie que le chariot est adapté au gabarit du véhicule et à la résistance de son plancher avant d'y entrer."),
("Vous déchargez depuis le sol une remorque à plateau. Comment répartissez-vous les prises ?",
 "En alternant les côtés", ["Tout d'un côté d'abord", "Par l'arrière seulement", "Au hasard des colis"],
 "R489, annexe 2, savoir-faire : on équilibre les prises et les déposes de part et d'autre du véhicule pour maintenir sa stabilité."),
("L'intérieur de la remorque est sombre. Que faites-vous avant d'y entrer ?",
 "J'éclaire l'intérieur", ["J'entre à l'aveugle", "J'accélère pour sortir vite", "Je lève la charge pour voir"],
 "R489, annexe 2, savoir-faire : on recourt si besoin à un éclairage adapté à l'intérieur du véhicule ou sur le chariot."),
("Comment réglez-vous votre vitesse à l'entrée d'un camion à quai ?",
 "Je ralentis fortement", ["Je garde ma vitesse", "J'accélère sur le pont", "Je roule fourche haute"],
 "R489, annexe 2, savoir-faire : on adapte la vitesse et la trajectoire du chariot à l'entrée, à la sortie et à l'intérieur du véhicule."),
("Comment disposez-vous les charges dans une remorque ?",
 "Selon le plan de chargement", ["Au plus près de la porte", "Toutes au même endroit", "Les plus lourdes en haut"],
 "R489, annexe 2, savoir-faire : on prend et on dépose les charges conformément au plan de chargement, en répartissant la charge dans le volume utile."),
("Quand gerbez-vous une charge en hauteur, que doit faire le chariot ?",
 "Être à l'arrêt", ["Rouler au pas", "Tourner lentement", "Reculer doucement"],
 "INRS ED 766, § 3.6.1 : on élève la charge à la hauteur nécessaire le chariot étant à l'arrêt ; on ne lève pas en roulant."),
("Avant de poser une charge sur une pile, dans quelle position mettez-vous les fourches ?",
 "À l'horizontale", ["Inclinées vers l'avant", "Inclinées vers l'arrière", "À moitié écartées"],
 "INRS ED 766, § 3.6.1 : au-dessus de l'emplacement, on freine, on amène les bras de fourche à l'horizontale, puis on dépose lentement la charge."),
("Avant de reculer pour dégager une charge prise sur une pile, que faites-vous ?",
 "Je regarde derrière moi", ["Je lève la fourche au maximum", "J'incline le mât en avant", "Je klaxonne trois fois"],
 "INRS ED 766, § 3.6 : on soulève la charge, on incline le mât en arrière et, après avoir regardé derrière, on recule pour dégager la charge."),
("Pendant la montée d'une charge dans un rayonnage, que contrôlez-vous au passage à hauteur des yeux ?",
 "L'horizontalité", ["La pression des pneus", "La charge de la batterie", "Le niveau d'huile"],
 "INRS ED 766, § 3.6.2 : on contrôle l'horizontalité lors du passage de la charge à hauteur des yeux, avant de la présenter dans l'alvéole."),
("Comment entrez-vous les fourches dans une palette posée en rayonnage ?",
 "Mât vertical", ["Mât incliné en avant", "Mât incliné en arrière", "Fourche en biais"],
 "INRS ED 766, § 3.6.2 : on arrête le chariot devant le palettier, on redresse le mât à la verticale et on pénètre la fourche dans la palette mât vertical."),
("Vous empilez des charges au sol. Qu'appréciez-vous avant de poser un niveau de plus ?",
 "La stabilité de la pile", ["La couleur des palettes", "L'heure de la pause", "Le poids du chariot"],
 "R489, annexe 2, savoir-faire : on apprécie le nombre maximal de niveaux sans écroulement ni basculement de la pile avant de gerber."),
("Avant de stocker une palette, que vérifiez-vous sur elle ?",
 "Son état", ["Son prix d'achat", "Sa date de fabrication", "Sa couleur"],
 "R489, annexe 2, savoir-faire ; INRS ED 766, § 2.5 : on s'assure que la palette est en bon état et que le conditionnement est stable (banderolage) avant de la stocker."),
("Une palette a une planche cassée. Que faites-vous ?",
 "Je ne la stocke pas en hauteur", ["Je la monte au dernier niveau", "Je la stocke en biais", "Je la cale avec la fourche"],
 "INRS ED 766, § 2.5 : on s'assure que les palettes sont en bon état et adaptées aux conditions de stockage ; une palette abîmée peut céder en hauteur."),
("Vous devez transporter des tubes longs qui dépassent largement du chariot. Que faites-vous d'abord ?",
 "Je prévois une méthode", ["Je roule vite pour finir", "Je les prends par un bout", "Je les lève très haut"],
 "R489, annexe 2, savoir-faire : pour une charge longue, on définit une méthode de prise et de manutention qui assure la stabilité et on prévoit les moyens adaptés."),
("Pourquoi rouler très doucement avec un fût rempli de liquide ?",
 "Le liquide se déplace", ["Le fût chauffe en roulant", "Le liquide s'évapore", "Le fût se vide par le haut"],
 "R489, annexe 2, savoir-faire : un contenant rigide rempli de liquide demande une méthode adaptée, car le liquide qui bouge déplace le centre de gravité au freinage et en virage."),
("Un big-bag déformable doit être déplacé. Quel est le meilleur choix ?",
 "Un support à big-bags", ["Un bras de fourche levé", "Une corde sur la fourche", "Un crochet improvisé"],
 "INRS ED 949, § 2.4 : suspendre un big-bag à la fourche ou à un bras levé cause des renversements ; on utilise des supports spécialement conçus."),
("Vous chargez un chariot sur un porte-engin. Que vérifiez-vous sur sa masse ?",
 "Qu'elle convient à l'engin", ["Qu'elle dépasse 3 t", "Qu'elle est inscrite au sol", "Qu'elle égale la charge levée"],
 "R489, annexe 2, savoir-faire : on vérifie que la masse du chariot est compatible avec la capacité de l'engin de transport et qu'il peut franchir le plan incliné."),
("Le chariot est chargé sur le porte-engin. Que faites-vous ensuite ?",
 "Je l'amarre aux points prévus", ["Je laisse la fourche haute", "Je laisse le moteur en marche", "Je retire les cales"],
 "R489, annexe 2, savoir-faire : après le chargement, on met le chariot en configuration de transport et on identifie ses points d'amarrage pour l'arrimer."),
]
